SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", SUM(FAILSAFE_BYTES) AS "STORAGE_FAILSAFE_BYTES" FROM (SELECT d."DATABASE_NAME" AS DATABASE_NAME, d."DATABASE_ID" AS DATABASE_ID, CAST(d."USAGE_DATE" AS DATE) AS USAGE_DAY, d."AVERAGE_DATABASE_BYTES" AS ACTIVE_BYTES, d."AVERAGE_FAILSAFE_BYTES" AS FAILSAFE_BYTES, COALESCE(d."AVERAGE_HYBRID_TABLE_STORAGE_BYTES", 0) AS HYBRID_TABLE_BYTES, LAG(d."AVERAGE_DATABASE_BYTES") OVER (PARTITION BY d."DATABASE_NAME", (NULL) ORDER BY CAST(d."USAGE_DATE" AS DATE)) AS ACTIVE_BYTES_PRIOR_DAY /* Yesterday's figure for the same database. Computed over the whole */ /* retained window, so the first day inside a requested range still has a */ /* comparison point instead of a null growth rate. */, a."STORAGE_BYTES" AS ACCOUNT_STORAGE_BYTES, a."STAGE_BYTES" AS ACCOUNT_STAGE_BYTES, a."FAILSAFE_BYTES" AS ACCOUNT_FAILSAFE_BYTES, (NULL) AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM database_storage_usage_history AS d LEFT JOIN storage_usage AS a ON CAST(a."USAGE_DATE" AS DATE) = CAST(d."USAGE_DATE" AS DATE) AND COALESCE((NULL), '') = COALESCE((NULL), '')) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "STORAGE_FAILSAFE_BYTES" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
